   "title": "精熟題第 2 題",
   "q": "如圖一，\\(\\overline{OP}\\) 為一條拉直的細線，\\(A\\)、\\(B\\) 兩點在 \\(\\overline{OP}\\) 上，且 \\(\\overline{OA}：\\overline{AP}=1：3\\)，\\(\\overline{OB}：\\overline{BP}=5：7\\)。若先固定 \\(B\\) 點，將 \\(\\overline{OB}\\) 摺向 \\(\\overline{BP}\\)，使得 \\(\\overline{OB}\\) 重疊在 \\(\\overline{BP}\\) 上（圖二），再從圖三的 \\(A\\) 點及與 \\(A\\) 點重疊的 \\(A'\\) 點一起剪開，使細線分成三段，則這三段分別為 \\(\\overline{OA}\\)、\\(\\overline{AA'}\\) 與 \\(\\overline{A'P}\\)，求 \\(\\overline{OA}：\\overline{AA'}：\\overline{A'P}\\)。\n承上，設 \\(\\overline{OB}=5r\\)、\\(\\overline{BP}=7r\\)（\\(r≠0\\)），則 \\(\\overline{OP}=12r\\)。固定 \\(B\\) 點把 \\(\\overline{OB}\\) 摺向 \\(\\overline{BP}\\)：\n承上，\\(\\overline{OP}=12r\\)、\\(\\overline{BP}=7r\\)。\n承上，\\(\\overline{AB}=2r\\)。摺好後 \\(A\\) 與 \\(\\overline{BP}\\) 上的 \\(A'\\) 重疊，從這一點剪開，細線分成三段。",
   "ref": "圖一、圖二、圖三見習作 p.7",
   "steps": [
    "\\(\\overline{OA}=12r×\\frac{1}{1+3}=3r\\)，\\(\\overline{AP}=12r-3r=9r\\)",
    "\\(\\overline{AB}=\\overline{AP}-\\overline{BP}=9r-7r=2r\\)",
    "\\(\\overline{AA'}=2\\overline{AB}=4r\\)，\\(\\overline{A'P}=\\overline{BP}-\\overline{AB}=7r-2r=5r\\)",
    "故 \\(\\overline{OA}：\\overline{AA'}：\\overline{A'P}=3r：4r：5r=3：4：5\\)"
   ],
