   "q": "圖一為正三角形紙片 \\(ABC\\)。以 \\(\\overline{DE}\\) 為摺線把 \\(A\\) 往下摺後，\\(\\overline{AD}\\)、\\(\\overline{AE}\\) 交 \\(\\overline{BC}\\) 於 \\(F\\)、\\(G\\)（圖二）。已知 \\(\\overline{BD}=5\\)、\\(\\overline{BF}=8\\)、\\(\\overline{DF}=7\\)、\\(\\overline{AF}=4\\)。\n承上，\\(\\overline{BD}=5\\)、\\(\\overline{BF}=8\\)、\\(\\overline{DF}=7\\)、\\(\\overline{AF}=4\\)。\n承上，\\(\\triangle BFD \\sim \\triangle AFG\\)、\\(\\overline{BC}=16\\)。",
