   "q": "如圖，四邊形 \\(ABCD\\) 為平行四邊形，\\(E\\) 為 \\(\\overline{CD}\\) 延長線上的一點，\\(\\overline{BE}\\) 交 \\(\\overline{AD}\\) 於 \\(F\\) 點、交 \\(\\overline{AC}\\) 於 \\(G\\) 點。若 \\(\\overline{BG}=6\\)，\\(\\overline{GF}=3\\)，求 ① \\(\\overline{AG}：\\overline{GC}\\)　② \\(\\overline{EF}\\) 的長。\n承上，\\(\\overline{BG}=6\\)、\\(\\overline{GF}=3\\)。\n承上，\\(\\overline{AG}：\\overline{GC}=1：2\\)。",
