   "q": "如圖，在等腰直角三角形 \\(ABC\\) 中，\\(\\angle A=\\angle B=45\\degree\\)，\\(\\angle C=90\\degree\\)。若 \\(\\overline{AB}=6\\)，求 \\(\\overline{AC}\\) 的長。\n承上，\\(\\angle A=\\angle B=45\\degree\\)、\\(\\angle C=90\\degree\\)、\\(\\overline{AB}=6\\)。",
