   "q": "右圖是捷運電扶梯的側面圖，\\(\\overline{DE}\\) 為水平地面。已知電扶梯的高度 \\(\\overline{BC}\\) 為 \\(350\\) 公分，斜面 \\(\\overline{AB}\\) 與水平地面 \\(\\overline{DE}\\) 呈 \\(30\\degree\\) 夾角，則電扶梯斜面 \\(\\overline{AB}\\) 的長度為多少公分？\n承上，\\(\\overline{BC}=350\\) 公分，\\(\\angle BAC=30\\degree\\)。",
