   "title": "隨堂練習 課P76",
   "q": "如圖，直角三角形 \\(ABC\\) 中 \\(\\angle C=90\\degree\\)，\\(\\overline{AC}：\\overline{BC}：\\overline{AB}=5：12：13\\)。將下列比值以 \\(\\sin B\\)、\\(\\cos B\\)、\\(\\tan B\\) 表示。\n① \\(\\frac{5}{13}\\)　② \\(\\frac{5}{12}\\)　③ \\(\\frac{12}{13}\\)\n承上，\\(\\angle C=90\\degree\\)，\\(\\overline{AC}：\\overline{BC}：\\overline{AB}=5：12：13\\)。",
   "ref": "圖見課本 p.76",
   "steps": [
    "\\(\\angle B\\) 的對邊 \\(\\overline{AC}\\)、鄰邊 \\(\\overline{BC}\\)、斜邊 \\(\\overline{AB}\\)",
    "① \\(\\frac{5}{13}=\\frac{\\overline{AC}}{\\overline{AB}}=\\sin B\\)　② \\(\\frac{5}{12}=\\frac{\\overline{AC}}{\\overline{BC}}=\\tan B\\)",
    "③ \\(\\frac{12}{13}=\\frac{\\overline{BC}}{\\overline{AB}}=\\cos B\\)"
   ],
   "ans": "① \\(\\sin B\\)　② \\(\\tan B\\)　③ \\(\\cos B\\)",
