   "q": "如圖，將一張面積為 \\(25\\) 的大三角形紙片沿著虛線剪成三張小三角形紙片與一張平行四邊形紙片。已知 \\(\\overline{DE}=4\\)，\\(\\overline{BC}=10\\)，求 \\(\\parallelogram DEFG\\) 的面積。\n承上，\\(\\overline{DE}=4\\)、\\(\\overline{BC}=10\\)、\\(\\triangle ABC\\) 的面積為 \\(25\\)。\n承上，高之比 \\(a：b=2：5\\)，\\(\\triangle ABC\\) 的面積為 \\(25\\)。",
