   "title": "基礎題第 2 題",
   "q": "已知圓 \\(O\\) 的半徑為 \\(8\\)，回答下列問題：\n① 判別下列直線與圓 \\(O\\) 的交點個數：圓心 \\(O\\) 到 \\(L_1\\)、\\(L_2\\)、\\(L_3\\) 的距離分別為 \\(7\\)、\\(8\\)、\\(9\\)\n② \\(L_1\\)、\\(L_2\\)、\\(L_3\\) 中哪一條是圓 \\(O\\) 的切線？\n③ \\(L_1\\)、\\(L_2\\)、\\(L_3\\) 中哪一條是圓 \\(O\\) 的割線？\n承上，半徑 \\(8\\)，圓心 \\(O\\) 到 \\(L_1\\)、\\(L_2\\)、\\(L_3\\) 的距離為 \\(7\\)、\\(8\\)、\\(9\\)。",
