   "q": "如圖，\\(\\overline{AB}\\) 為圓 \\(O\\) 的一弦，且 \\(C\\) 點在 \\(\\overline{AB}\\) 上。若 \\(\\overline{AC}=5\\)，\\(\\overline{BC}=1\\)，\\(\\overline{AB}\\) 的弦心距為 \\(2\\)，求 \\(\\overline{OC}\\) 的長。\n承上，\\(\\overline{AC}=5\\)、\\(\\overline{BC}=1\\)、弦心距 \\(=2\\)。",
