   "q": "【已知】如圖，在 \\(\\triangle ABC\\) 中，\\(\\angle B=\\angle C\\)，\\(\\overline{AD} \\perp \\overline{BC}\\)。【求證】\\(\\overline{AB}=\\overline{AC}\\)。\n【證明】在 \\(\\triangle ABD\\) 與 \\(\\triangle ACD\\) 中：",
