   "q": "「任一個奇數乘以任一個偶數」你會猜測得到奇數還是偶數呢？根據結論證明你的猜測是正確的。\n【已知】\\(a\\) 是奇數，\\(b\\) 是偶數。　【求證】\\(a×b\\) 是偶數。",
