   "q": "如圖，在 \\(\\triangle ABC\\) 中，\\(D\\)、\\(E\\) 為 \\(\\overline{AC}\\)、\\(\\overline{AB}\\) 的中點，且 \\(\\overline{BD}\\)、\\(\\overline{CE}\\) 交於 \\(G\\) 點。若 \\(\\overline{GG'}\\) 與 \\(\\overline{DD'}\\) 皆垂直於 \\(\\overline{BC}\\)，求 \\(\\overline{GG'}：\\overline{DD'}\\)。\n【解】",
