   "q": "下列敘述正確打「\\(\\bigcirc\\)」，不正確打「\\(\\times\\)」：\n① 圓 \\(O\\) 的直徑為 \\(6\\)，若 \\(\\overline{OP}=3\\)，則 \\(P\\) 點在圓 \\(O\\) 上。\n② \\(A\\) 點為圓 \\(O\\) 上之一點，若直線 \\(L\\) 通過 \\(A\\) 點，則直線 \\(L\\) 稱為圓 \\(O\\) 的切線。\n③ 在同一圓中，弦心距愈長，則所對應的弦愈長。\n（續）下列敘述正確打「\\(\\bigcirc\\)」，不正確打「\\(\\times\\)」：\n④ 圓 \\(O\\) 的半徑為 \\(8\\)，若圓心到直線 \\(L\\) 的距離為 \\(6\\)，則直線 \\(L\\) 與圓 \\(O\\) 有 \\(2\\) 個交點。\n⑤ 在同一圓中，度數愈大的弧，其長度愈長。\n⑥ \\(\\overline{AB}\\)、\\(\\overline{CD}\\) 為圓 \\(O\\) 的兩弦，若 \\(\\overline{AB} \\parallel \\overline{CD}\\)，則 \\(\\overarc{AB}=\\overarc{CD}\\)。\n【逐項判斷】",
