   "q": "如圖，\\(\\overarc{AC}\\)、\\(\\overarc{BD}\\) 皆為半圓，且相交於 \\(E\\) 點，其中 \\(A\\)、\\(B\\)、\\(C\\)、\\(D\\) 在同一直線上，且 \\(B\\) 為 \\(\\overline{AC}\\) 的中點。若 \\(\\overarc{CE}=50\\degree\\)，求 \\(\\angle EBC\\) 與 \\(\\overarc{BE}\\) 的度數。\n承上，\\(\\overarc{CE}=50\\degree\\)。",
