   "q": "如圖，兩個圓的圓心皆為 \\(O\\) 點，其中小圓為池塘，圓環為草坪。傑克用一條長 \\(10\\) 公尺的繩子 \\(\\overline{AB}\\) 作為大圓的一弦，剛好與小圓相切，求圓環草坪的面積。\n設大圓半徑為 \\(R\\)、小圓半徑為 \\(r\\)，\\(\\overline{AB}\\) 與小圓相切於 \\(M\\) 點。",
