   "q": "如圖，在坐標平面上，\\(A\\)、\\(B\\) 分別為圓 \\(P\\) 與 \\(y\\) 軸、\\(x\\) 軸的交點，直線 \\(L\\) 通過 \\(P\\) 且與 \\(\\overline{AB}\\) 垂直，\\(C\\) 為 \\(L\\) 與 \\(x\\) 軸的交點。\\(A\\)、\\(B\\)、\\(C\\) 的坐標為 \\(（0，a）\\)、\\(（4，0）\\)、\\(（-6，0）\\)，\\(a>0\\)。\n求 ① \\(\\overline{AC}\\) 的長　② \\(a\\) 的值。\n① \\(\\because\\) 直線 \\(L\\) 通過圓心 \\(P\\) 點且與 \\(\\overline{AB}\\) 垂直\n② 在直角三角形 \\(AOC\\) 中，\\(\\overline{AC}=10\\)、\\(\\overline{CO}=6\\)。",
