   "q": "〈禮盒設計〉甲、乙兩款喜餅禮盒皆為長 \\(40\\) 公分、寬 \\(30\\) 公分的長方形。甲禮盒內有 \\(12\\) 個大小相同的圓形喜餅，乙禮盒內有 \\(2\\) 個。\n兩款禮盒每個喜餅的半徑分別為多少公分？（不考慮隔板厚度）\n乙禮盒：兩個喜餅分別內切於對角線分出的兩個直角三角形。\n【解】",
   "ref": "圖見習作 p.58。原書題幹是兩盒實物喜餅的照片，成品改用原書第 1 題的幾何版本（長方形內排圓）",
